Action: run_sql({'query': "SELECT \n    e.gmap_id,\n    e.name,\n    e.address,\n    e.avg_rating,\n    e.num_of_reviews,\n    e.price,\n    ST_Y(e.geom) as lat,\n    ST_X(e.geom) as lon,\n    STRING_AGG(DISTINCT c.category, ', ') as categories\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nWHERE ST_Distance(e.geom, ST_Point(-111.925, 40.782)) * 69.0 < 3.0\nGROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.geom\nHAVING LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%breakfast%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%brunch%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%diner%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%cafe%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%mexican%'\n    OR LOWER(STRING_AGG(DISTINCT c.category, ', ')) LIKE '%burrito%'\n    OR LOWER(e.name) LIKE '%breakfast%'\n    OR LOWER(e.name) LIKE '%cafe%'\n    OR LOWER(e.name) LIKE '%diner%'\n    OR LOWER(e.name) LIKE '%taco%'\n    OR LOWER(e.name) LIKE '%burrito%'\nORDER BY e.avg_rating DESC, e.num_of_reviews DESC\nLIMIT 30"})

