Action: run_sql({'query': "SELECT \n    e.gmap_id,\n    e.name,\n    e.address,\n    e.avg_rating,\n    e.num_of_reviews,\n    e.price,\n    ST_Y(e.geom) as lat,\n    ST_X(e.geom) as lon,\n    STRING_AGG(DISTINCT c.category, ', ') as categories\nFROM establishments e\nLEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nLEFT JOIN category c ON ec.category_id = c.category_id\nWHERE e.address LIKE '%84116%' OR e.address LIKE '%Rose Park%' OR (ST_Distance(e.geom, ST_Point(-111.925, 40.782)) * 69.0 < 2.0)\nGROUP BY e.gmap_id, e.name, e.address, e.avg_rating, e.num_of_reviews, e.price, e.geom\nORDER BY e.avg_rating DESC, e.num_of_reviews DESC\nLIMIT 50"})

